SELECT DISTINCT r."TR_KEY", r."typeFlag"
FROM main.trade_records AS t
JOIN main.traders AS r ON r."TR_KEY" = t.tr_anchor
WHERE (
    CAST((t.trade_perf->>'lev_ratio') AS DOUBLE) > 5.0
    AND (r.trader_fin_data->>'risk_lvl') = 'Aggressive'
) OR (
    t.vol_day / NULLIF(
        CAST(
            REPLACE(
                REPLACE(TRIM((r.trader_fin_data->>'usd_bal')), '$', ''),
                ',',
                ''
            ) AS DOUBLE
        ),
        0
    ) > 0.5
)
ORDER BY r."TR_KEY";
